# rubik.s - Stage 4: optimal 2x2x2 solver (IDA*) in RV32I for Ripes.
#
# Build for the CLI:  cat ida/rubik.s ida/tables.s > /tmp/build.s
# (tables.s is generated by ida/pdb.c and holds perm_R.., ori_R..,
#  perm_pdb, ori_pdb, perm_row, ori_row)
#
# Exit codes: 0 = solved and verified, 1 = path check failed, 2 = invalid input

.data
fact:   .half 720, 120, 24, 6, 2, 1, 1     # (6 - i)!: Lehmer code weights
state:  .string "21345671111111"           # input: 7 cubie digits, 7 orientation digits
        .align 2                           # tables.s continues .data with .half tables

.text
main:
    # ---------------------------------------------------------------
    # 1. Parse the input.  Result: s0 = p (0..5039), s1 = o (0..728).
    #    Any problem jumps to `invalid`.
    # ---------------------------------------------------------------

    # a0 = address of state

    # (1) Length: bytes 0..13 are non-zero, byte 14 is zero.
    la   t0, state          # pointer
    mv   t1, t0             # keep the start

len_loop:
    lbu  t2, 0(t0)          # current character
    beqz t2, len_done       # '\0' => done
    addi t0, t0, 1          # ptr++
    j    len_loop

len_done:
    sub  t3, t0, t1         # length = ptr - start
    li   t4, 14             # expected length
    bne  t3, t4, invalid    # length != 14

    # (2) Permutation digits, i = 0..6:
    #       c = state[i] - '1'
    #       c must be 0..6         (one unsigned compare catches c < 0 too)
    #       bit c of a "seen" mask must be clear, then set it
    #     No final seen == 0x7F check: 7 digits, each 0..6, none repeated,
    #     must be 0..6 exactly once (pigeonhole).
    la   t0, state          # pointer
    li   t4, 0              # seen = 0
    li   t5, 7              # counter
    li   t6, 7              # upper bound

perm_loop:
    lbu  t2, 0(t0)          # character
    addi t2, t2, -49        # c = character - '1'
    bgeu t2, t6, invalid    # c >= 7 (unsigned) => invalid

    li   t3, 1              # bit = 1
    sll  t3, t3, t2         # bit = 1 << c

    and  t1, t4, t3         # tmp = seen & bit
    bnez t1, invalid        # seen before

    or   t4, t4, t3         # seen |= bit

    addi t0, t0, 1          # ptr++
    addi t5, t5, -1         # counter--
    bnez t5, perm_loop

    # (3) Orientation digits, i = 0..6:
    #       d = state[7 + i] - '1'
    #       d must be 0..2
    #       sum += d
    #       for i < 6 only: o = o * 3 + d      (no multiply: shift + add)
    #     sum mod 3 must be 0      (sum <= 14: subtract 3 while sum >= 3)
    #     One loop of 7 with a skip for the 7th o update: parse runs once,
    #     so code size wins over the extra branch per iteration.
    #     t0 already points at state[7]

    li   s1, 0              # o = 0
    li   t1, 0              # sum_mod3 = 0
    li   t5, 7              # counter = 7
    li   t6, 3              # range limit and mod-3 constant

ori_loop:
    lbu  t2, 0(t0)          # read digit
    addi t2, t2, -49        # d = digit - '1'
    bgeu t2, t6, invalid    # d >= 3 => invalid

    # sum_mod3 = (sum_mod3 + d) mod 3
    add  t1, t1, t2         # sum_mod3 += d
    addi t3, t1, -3         # tmp = sum_mod3 - 3
    bltz t3, ori_skip       # if tmp < 0, keep old value
    mv   t1, t3             # sum_mod3 = tmp

ori_skip:

    # skip o update for the 7th digit
    li   t4, 1
    beq  t5, t4, ori_next

    slli t3, s1, 1          # tmp = o << 1
    add  s1, s1, t3         # o = o * 3
    add  s1, s1, t2         # o = o * 3 + d

ori_next:
    addi t0, t0, 1          # ptr++
    addi t5, t5, -1         # counter--
    bnez t5, ori_loop

    bnez t1, invalid        # sum_mod3 must be 0

    # (4) Lehmer code, i = 0..6:
    #       w = fact[i]
    #       for j = i + 1..6: if state[j] < state[i], p += w
    #     (comparing the ASCII digits directly keeps their order)
    #     The outer loop stops at i = 5: for i = 6 there is no j.
    li   s0, 0              # p = 0
    la   t0, state          # i pointer
    la   t5, fact           # weight pointer
    la   t6, state+7        # end
    addi t4, t6, -1         # outer_end = &state[6]

lehmer_outer:
    lbu  t2, 0(t0)          # state[i]
    lhu  t3, 0(t5)          # w = fact[i]
    addi t1, t0, 1          # j = i + 1

lehmer_inner:
    lbu  a0, 0(t1)          # state[j]
    bgeu a0, t2, lehmer_skip
    add  s0, s0, t3         # p += w

lehmer_skip:
    addi t1, t1, 1          # j++
    bltu t1, t6, lehmer_inner

    addi t0, t0, 1          # i++
    addi t5, t5, 2          # next .half
    bltu t0, t4, lehmer_outer

    # ---------------------------------------------------------------
    # Temporary check of step 1: print p and o, then exit 0.
    # (removed once the search is written)
    # ---------------------------------------------------------------
    mv   a0, s0             # print p
    li   a7, 1
    ecall
    li   a0, 32             # print a space
    li   a7, 11
    ecall
    mv   a0, s1             # print o
    li   a7, 1
    ecall

    li a0, 0
    li a7, 93
    ecall

invalid:
    li a0, 2
    li a7, 93
    ecall
